mapper.select:
SELECT 



 ORDER BY ${sortColumn} ${sortDirection}, i.inbound_seq DESC

    LIMIT #{size} OFFSET #{offset}

mapper.insert:
INSERT INTO tb_inbound (
    inbound_no, inbound_type, order_seq, plant_seq, warehouse_seq,
    supplier_seq, planned_date, inbound_status, remark, created_by
) VALUES (
    #{inboundNo}, #{inboundType}, #{orderSeq}, #{plantSeq}, #{warehouseSeq},
    #{supplierSeq}, #{plannedDate}, #{inboundStatus}, #{remark}, #{createdBy}
)

INSERT INTO tb_inbound_line (
    inbound_seq, line_no, sku_seq, order_line_seq, planned_qty, remark, created_by
) VALUES (
    #{inboundSeq}, #{lineNo}, #{skuSeq}, #{orderLineSeq}, #{plannedQty},
    #{remark}, #{createdBy}
)

mapper.select:
SELECT COALESCE(SUM(l.planned_qty), 0)
  FROM tb_inbound_line l
  JOIN tb_inbound i ON i.inbound_seq = l.inbound_seq
 WHERE l.order_line_seq = #{orderLineSeq}
   AND i.inbound_status <> 'CANCELED'

   AND i.inbound_seq <> #{exceptInboundSeq}
